package com.yihe.framework.ehr;
import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;
import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
@SuppressWarnings("unchecked") public class OccupationalScreeningChecks {
 static final ObjectMapper JSON=new ObjectMapper();static int checks;
 static void check(String name,boolean ok){if(!ok)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 static String encode(Object v){try{return JSON.writeValueAsString(v);}catch(Exception e){throw new RuntimeException(e);}}
 static void reject(String name,Runnable call){try{call.run();throw new AssertionError(name);}catch(EhrException e){check(name,e.status==503);}}
 static Map<String,Object> output(Map<String,Object> model){List<Object> factors=new ArrayList<>();for(String f:OccupationalScreening.FACTORS)factors.add(map("factor",f,"status",f.equals("noise")?"recorded":"not_recorded","evidence_ids",f.equals("noise")?Arrays.asList("P-EXPOSURE"):new ArrayList<>(),"signal_ids",new ArrayList<>(),"analysis","依据已有接触记录和检查数据提供健康管理关注建议；没有现场测量资料。"));return map("schema_version",OccupationalScreening.FORMAT,"subject_ref",model.get("subject_ref"),"summary","隔离测试：资料仅用于验证流程，不作现实诊疗判断。","suggested_risk","low","risk_rationale","有接触记录，缺少现场测量，未据此认定高暴露。","factors",factors,"history_analysis","仅比较提供的同指标同单位结果，无历史资料则不推算。","recommendations",Arrays.asList("核实岗位防护资料"),"doctor_attention",Arrays.asList("由职业健康医生核实相关检查"),"limitations",Arrays.asList("现场接触强度未提供"));}
 public static void main(String[]args){Map<String,Object> report=map("id",id(),"revision",1,"examDate","2020-04-01","institution","测试机构","reviewStatus","needs_review","published",false,"items",Arrays.asList(map("id",id(),"name","听力","value","听力下降","abnormal","↑","unit","dB","referenceRange","原件范围","page",3),map("id",id(),"name","胸部检查","value","未见明显异常","abnormal","","page",2)),"conclusions",new ArrayList<>(),"advice",new ArrayList<>());Map<String,Object> source=map("name","测试职工甲","code","SECRET-CODE-01","identityNumber","110101199001011234","phone","13800138000","birth","1990-01-01","org","测试单位甲","age",36,"sex","男","job","井下机电维修工","exposure","煤尘；噪声","reports",Arrays.asList(report),"occupationalFields",new ArrayList<>(),"examAssessments",new ArrayList<>());
  OccupationalScreening.Input in=OccupationalScreening.prepare(source,"SUB-TEST-0001");String sent=encode(in.model);check("pseudonymous_input_no_personal_identifiers",!sent.contains("测试职工甲")&&!sent.contains("SECRET-CODE")&&!sent.contains("110101199001011234")&&!sent.contains("13800138000")&&!sent.contains("测试单位甲"));check("outbound_calendar_dates_removed",!sent.contains("2020-04-01")&&!sent.contains("1990-01-01")&&!sent.contains("examDate"));check("age_sex_job_exposure_preserved",sent.contains("井下机电维修工")&&sent.contains("煤尘；噪声")&&sent.contains("36"));check("raw_values_units_pages_preserved",sent.contains("听力下降")&&sent.contains("dB")&&sent.contains("原件范围"));check("normal_text_is_not_a_health_signal",!OccupationalScreening.signal(map("value","未见明显异常","abnormal","")));check("blank_is_not_normal",!OccupationalScreening.signal(map("value","","abnormal","")));
  check("numeric_outside_original_range_is_a_signal",OccupationalScreening.signal(map("value","6.277","referenceRange","0.350-5.100")));check("normal_numeric_not_a_signal",!OccupationalScreening.signal(map("value","5.23","referenceRange","3.5-9.5")));check("no_unprovided_reference_is_invented",!OccupationalScreening.signal(map("value","9.9","referenceRange","")));check("explicit_normal_flag_not_false_positive",!OccupationalScreening.signal(map("value","未见异常","abnormal","无异常")));
  Map<String,Object> out=output(in.model),result=OccupationalScreening.parse(encode(out),in);check("keyword_exposure_alone_not_high_risk",num(result.get("screeningScore"))==20&&"low".equals(result.get("screeningLevel")));check("five_domains_complete",((Map<?,?>)result.get("domains")).size()==5);check("exposure_not_measured",Boolean.FALSE.equals(result.get("exposureMeasured")));check("data_coverage_separate_from_health_score",num(OccupationalScreening.completeness(source).get("score"))==70);check("no_source_advice_required",!OccupationalScreening.plain(result).isEmpty());
  Map<String,Object> noise=(Map<String,Object>)((List<?>)out.get("factors")).get(1);noise.put("signal_ids",Arrays.asList("R1-OBS-1"));result=OccupationalScreening.parse(encode(out),in);check("health_signal_adds_auditable_score",num(result.get("screeningScore"))==50&&"medium".equals(result.get("screeningLevel")));check("evidence_local_report_link_resolved",encode(result.get("evidence")).contains(str(report.get("id"))));noise.put("signal_ids",Arrays.asList("invented"));reject("fabricated_evidence_rejected",()->OccupationalScreening.parse(encode(out),in));noise.put("signal_ids",Arrays.asList("R1-OBS-2"));reject("normal_observation_cannot_raise_score",()->OccupationalScreening.parse(encode(out),in));noise.put("signal_ids",Arrays.asList("R1-OBS-1","R1-OBS-1"));reject("duplicate_signal_cannot_inflate_score",()->OccupationalScreening.parse(encode(out),in));noise.put("signal_ids",new ArrayList<>());noise.put("evidence_ids",Arrays.asList("P-JOB"));reject("job_inference_not_recorded_exposure",()->OccupationalScreening.parse(encode(out),in));noise.put("status","inferred");result=OccupationalScreening.parse(encode(out),in);check("job_inference_marked_unconfirmed",num(result.get("screeningScore"))==10);out.put("subject_ref","SUB-OTHER-1234");reject("response_subject_mismatch_rejected",()->OccupationalScreening.parse(encode(out),in));out.put("subject_ref",in.model.get("subject_ref"));out.put("summary","伪造依据 R1-OBS-9999");reject("textual_fabricated_citation_rejected",()->OccupationalScreening.parse(encode(out),in));out.put("summary","隔离测试摘要");out.put("suggested_risk","unknown");reject("completed_output_requires_ai_risk_suggestion",()->OccupationalScreening.parse(encode(out),in));reject("plain_text_not_fake_completed",()->OccupationalScreening.parse("这是一份建议",in));
  System.out.println("PASS occupational screening checks: "+checks);
 }
}
